<?php
require_once __DIR__ . '/../auth/auth.php';
wajib_izin('modul_hr');
require_once __DIR__ . '/../config/koneksi_sqlsrv.php';

function h($v){ return htmlspecialchars((string)($v ?? ''), ENT_QUOTES, 'UTF-8'); }
function kategoriBerikutnya($conn, $pegawaiId, $tanggal){
    $rs=sqlsrv_query($conn, "SELECT COUNT(*) AS total, MAX(tanggal_sp) AS terakhir FROM dbo.surat_peringatan WHERE pegawai_id=? AND tanggal_sp <= ?", [$pegawaiId,$tanggal]);
    $r=$rs?sqlsrv_fetch_array($rs,SQLSRV_FETCH_ASSOC):[];
    $total=(int)($r['total']??0);
    $rsAktif=sqlsrv_query($conn, "SELECT COUNT(*) AS jumlah FROM dbo.surat_peringatan WHERE pegawai_id=? AND tanggal_sp > DATEADD(MONTH,-3,?) AND tanggal_sp <= ?", [$pegawaiId,$tanggal,$tanggal]);
    $jumlah=(int)(($rsAktif?sqlsrv_fetch_array($rsAktif,SQLSRV_FETCH_ASSOC)['jumlah']:0)??0);
    $terakhir=$r['terakhir'] instanceof DateTime ? $r['terakhir']->format('Y-m-d') : ($r['terakhir']??null);
    return ['kategori'=>$jumlah===0?'SP I':'SP '.min($jumlah+1,3), 'jumlah'=>$jumlah, 'terakhir'=>$terakhir, 'bersih'=>$jumlah===0, 'pemutihan'=>$jumlah===0&&$total>0];
}
function pegawaiAktif($conn){
    $rows=[]; $rs=sqlsrv_query($conn,"SELECT p.id_peg,p.nik,p.nama_peg,u.nama_unit FROM dbo.pegawai p LEFT JOIN dbo.unit_kerja u ON u.id=p.unit_kerja_id WHERE ISNULL(p.is_aktif,1)=1 ORDER BY p.nama_peg");
    while($rs && ($r=sqlsrv_fetch_array($rs,SQLSRV_FETCH_ASSOC))) $rows[]=$r; return $rows;
}
if(($_GET['aksi']??'')==='status'){
    header('Content-Type: application/json; charset=utf-8'); $id=(int)($_GET['pegawai_id']??0); $tgl=$_GET['tanggal']??date('Y-m-d');
    echo json_encode($id?kategoriBerikutnya($conn,$id,$tgl):['kategori'=>'SP I','jumlah'=>0,'terakhir'=>null,'bersih'=>true]); exit;
}
$pesan='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    $pegawaiId=(int)($_POST['pegawai_id']??0); $tanggal=$_POST['tanggal_sp']??date('Y-m-d'); $jenis=trim($_POST['jenis_pelanggaran']??'');
    $kronologi=trim($_POST['kronologi']??''); $dasar=trim($_POST['dasar_pelanggaran']??''); $tindakan=trim($_POST['tindakan']??'');
    $tempat=trim($_POST['tempat_pelanggaran']??''); $pukul=trim($_POST['pukul_pelanggaran']??'');
    $saksi=trim($_POST['saksi_bukti']??''); $kerugian=trim($_POST['kerugian_material']??''); $skorsing=trim($_POST['lama_skorsing']??'');
    $kategori=kategoriBerikutnya($conn,$pegawaiId,$tanggal);
    if(!$pegawaiId||!$jenis) $pesan='<div class="alert alert-danger">Pegawai dan jenis pelanggaran wajib diisi.</div>'; else {
        $bulan=date('Ym',strtotime($tanggal)); $rs=sqlsrv_query($conn,"SELECT COUNT(*)+1 AS n FROM dbo.surat_peringatan WHERE no_surat LIKE ?",['SP-'.$bulan.'-%']); $urut=(int)(($rs?sqlsrv_fetch_array($rs,SQLSRV_FETCH_ASSOC)['n']:1)??1); $no=sprintf('SP-%s-%03d',$bulan,$urut); $u=user_login();
        $st=sqlsrv_query($conn,"INSERT INTO dbo.surat_peringatan (no_surat,pegawai_id,tanggal_sp,kategori_sp,status_pemutihan,jenis_pelanggaran,kronologi,dasar_pelanggaran,tindakan,dibuat_oleh,tempat_pelanggaran,pukul_pelanggaran,saksi_bukti,kerugian_material,lama_skorsing) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",[$no,$pegawaiId,$tanggal,$kategori['kategori'],$kategori['pemutihan']?1:0,$jenis,$kronologi?:null,$dasar?:null,$tindakan?:null,$u['nama_lengkap']??null,$tempat?:null,$pukul?:null,$saksi?:null,$kerugian?:null,$skorsing?:null]);
        $pesan=$st?'<div class="alert alert-success">Surat <strong>'.h($no).'</strong> tersimpan sebagai <strong>'.h($kategori['kategori']).'</strong>.</div>':'<div class="alert alert-danger">Gagal menyimpan surat peringatan.</div>';
    }
}
$pegawai=pegawaiAktif($conn); $daftar=sqlsrv_query($conn,"SELECT s.*,p.nama_peg,p.nik FROM dbo.surat_peringatan s JOIN dbo.pegawai p ON p.id_peg=s.pegawai_id ORDER BY s.tanggal_sp DESC,s.id_sp DESC");
$page_title='Surat Peringatan'; include '../template/header.php'; include '../template/sidebar.php';
?>
<main id="main" class="main"><div class="pagetitle"><h1>Surat Peringatan</h1><nav><ol class="breadcrumb"><li class="breadcrumb-item"><a href="../index.php">Home</a></li><li class="breadcrumb-item active">Surat Peringatan</li></ol></nav></div><section class="section"><div class="row"><div class="col-lg-5"><div class="card"><div class="card-body"><h5 class="card-title">Form Surat Peringatan</h5><?= $pesan ?><form method="POST"><div class="mb-2"><label class="form-label">Karyawan</label><select name="pegawai_id" id="pegawai_id" class="form-select" required><option value="">Pilih karyawan</option><?php foreach($pegawai as $p): ?><option value="<?=h($p['id_peg'])?>"><?=h(($p['nik']??'').' - '.$p['nama_peg'].' ('.($p['nama_unit']??'').')')?></option><?php endforeach; ?></select></div><div class="row"><div class="col-md-6 mb-2"><label class="form-label">Tanggal SP</label><input type="date" name="tanggal_sp" id="tanggal_sp" class="form-control" value="<?=date('Y-m-d')?>" required></div><div class="col-md-6 mb-2"><label class="form-label">Kategori otomatis</label><input id="kategori" class="form-control kategori" value="SP I" readonly><small id="status3bulan" class="text-muted">Belum ada SP aktif</small></div></div><div class="mb-2"><label class="form-label">Jenis Pelanggaran</label><input name="jenis_pelanggaran" class="form-control" maxlength="255" required></div><div class="mb-2"><label class="form-label">Kronologi Kejadian</label><textarea name="kronologi" class="form-control" rows="3"></textarea></div><div class="mb-2"><label class="form-label">Dasar Pelanggaran</label><textarea name="dasar_pelanggaran" class="form-control" rows="2"></textarea></div><div class="row"><div class="col-md-6 mb-2"><label class="form-label">Tempat Kejadian</label><input name="tempat_pelanggaran" class="form-control" maxlength="150" placeholder="Line Corrugator 1"></div><div class="col-md-6 mb-2"><label class="form-label">Pukul (WIB)</label><input name="pukul_pelanggaran" class="form-control" maxlength="10" placeholder="07.25"></div><div class="col-md-6 mb-2"><label class="form-label">Saksi / Bukti</label><input name="saksi_bukti" class="form-control" maxlength="200"></div><div class="col-md-6 mb-2"><label class="form-label">Kerugian Material</label><input name="kerugian_material" class="form-control" maxlength="100" placeholder="-"></div><div class="col-md-6 mb-2"><label class="form-label">Lama Skorsing</label><input name="lama_skorsing" class="form-control" maxlength="50" placeholder="3 hari kerja"></div></div><div class="mb-3"><label class="form-label">Tindakan / Catatan</label><textarea name="tindakan" class="form-control" rows="2"></textarea></div><button class="btn btn-primary"><i class="bi bi-save"></i> Simpan Surat</button></form></div></div></div><div class="col-lg-7"><div class="card"><div class="card-body"><h5 class="card-title">Riwayat Surat Peringatan</h5><div class="table-responsive"><table class="table table-sm align-middle"><thead><tr><th>No Surat</th><th>Tanggal</th><th>Karyawan</th><th>Kategori</th><th>Aksi</th></tr></thead><tbody><?php $ada=false; while($r=$daftar?sqlsrv_fetch_array($daftar,SQLSRV_FETCH_ASSOC):false): $ada=true; ?><tr><td><?=h($r['no_surat'])?></td><td><?=$r['tanggal_sp'] instanceof DateTime?$r['tanggal_sp']->format('d-m-Y'):h($r['tanggal_sp'])?></td><td><?=h($r['nama_peg'])?><br><small><?=h($r['nik'])?></small></td><td><span class="badge bg-<?=$r['status_pemutihan']?'secondary':'danger'?>"><?=h($r['kategori_sp'])?></span><?php if($r['status_pemutihan']): ?><br><small class="text-muted">pemutihan</small><?php endif; ?></td><td><a class="btn btn-sm btn-outline-secondary" target="_blank" href="cetak.php?id=<?=$r['id_sp']?>" title="Cetak"><i class="bi bi-printer"></i></a></td></tr><?php endwhile; if(!$ada): ?><tr><td colspan="5" class="text-center text-muted">Belum ada surat.</td></tr><?php endif; ?></tbody></table></div></div></div></div></div></section></main><style>.kategori{font-weight:700;color:#b42318;background:#fff8f7}.form-label{font-size:.88rem;font-weight:600}</style><script>async function cekKategori(){const id=document.getElementById('pegawai_id').value,tgl=document.getElementById('tanggal_sp').value;if(!id)return;const r=await fetch('?aksi=status&pegawai_id='+encodeURIComponent(id)+'&tanggal='+encodeURIComponent(tgl));const d=await r.json();document.getElementById('kategori').value=d.kategori;document.getElementById('status3bulan').textContent=d.pemutihan?'Tidak ada SP dalam 3 bulan terakhir: pemutihan / SP bersih':(d.jumlah?'SP aktif dalam 3 bulan: '+d.jumlah+'; SP terakhir: '+d.terakhir:'Belum ada riwayat SP');}document.getElementById('pegawai_id').addEventListener('change',cekKategori);document.getElementById('tanggal_sp').addEventListener('change',cekKategori);</script><?php include '../template/footer.php'; ?>